        prompt_mode.update(cx, |this, _| this.output_table.scroll_to_top());
        frame(cx);
        frame(cx);
        still();
        wheel(cx, 40.);
        assert_eq!(built_up(cx), 40., "a scroll from the output's top didn't stretch");
