        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let height = self.slide_height.get();
        // From wherever the stretch had pulled the view.
        let (from, to) = if slide.up {
            (-height + slide.pull, px(0.))
        } else {
            (slide.pull, -height)
